using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Research Agent – searches the web for a topic, takes notes, then summarises.
// ---------------------------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

// Build the chat client with automatic function-invocation support.
IChatClient client = new ChatClientBuilder(
        new OpenAI.Chat.ChatClient("gpt-4o-mini", apiKey).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

// Shared state for the note-taking tool.
var notebook = new Notebook();

// Register the two tools.
var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) => WebSearchTool.SearchAsync(query),
        "web_search",
        "Search the web for information on a given query. Returns a list of results with titles, snippets, and URLs."),

    AIFunctionFactory.Create(
        ([Description("The note text to save")] string note) => notebook.AddNote(note),
        "take_note",
        "Save a research note. Use this to record key findings as you research."),

    AIFunctionFactory.Create(
        () => notebook.GetNotes(),
        "get_notes",
        "Retrieve all notes taken so far during research.")
};

// Ask the user for a topic.
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided – exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var chatOptions = new ChatOptions { Tools = tools };

List<ChatMessage> history =
[
    new(ChatRole.System, """
        You are a research assistant. The user will give you a topic.
        1. Use the web_search tool to find relevant, up-to-date information.
        2. Use the take_note tool to record the most important findings.
        3. Perform at least two different searches to get broad coverage.
        4. After gathering enough information, use get_notes to review your notes.
        5. Finally, write a concise summary (3-5 paragraphs) of your findings,
           citing sources where possible.
        """),
    new(ChatRole.User, $"Please research the following topic: {topic}")
];

// Run the agent loop – the FunctionInvokingChatClient handles tool calls automatically.
Console.ForegroundColor = ConsoleColor.DarkGray;
var response = await client.GetResponseAsync(history, chatOptions);
Console.ResetColor();

Console.WriteLine("\n── Research Summary ─────────────────────────────\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n── Notes Collected ──────────────────────────────\n");
foreach (var (i, note) in notebook.AllNotes.Select((n, i) => (i, n)))
{
    Console.WriteLine($"  [{i + 1}] {note}");
}

// ---------------------------------------------------------------------------
// Web-search tool (uses the DuckDuckGo Instant-Answer / HTML API as a
// lightweight, key-free search proxy).
// ---------------------------------------------------------------------------
static class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } }
    };

    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");
        try
        {
            var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
            var json = await Http.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            // Abstract / instant answer
            var abs = json.GetProperty("Abstract").GetString();
            var absUrl = json.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abs))
                results.Add($"[Summary] {abs} (source: {absUrl})");

            // Related topics
            if (json.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var t in topics.EnumerateArray().Take(8))
                {
                    if (t.TryGetProperty("Text", out var text) &&
                        t.TryGetProperty("FirstURL", out var tUrl))
                    {
                        results.Add($"- {text.GetString()} ({tUrl.GetString()})");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : $"No instant results for \"{query}\". Try rephrasing or a more specific query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }
}

// ---------------------------------------------------------------------------
// Notebook – simple in-memory note store.
// ---------------------------------------------------------------------------
class Notebook
{
    private readonly List<string> _notes = [];

    public IReadOnlyList<string> AllNotes => _notes;

    public string AddNote(string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        return string.Join("\n",
            _notes.Select((n, i) => $"[{i + 1}] {n}"));
    }
}

